css:
@keyframes tw{0%,100%{opacity:1}50%{opacity:.35}}
@keyframes fall{0%{transform:translateY(-6%) rotate(0)}100%{transform:translateY(106%) rotate(200deg)}}
@keyframes drift{0%{transform:translateY(-8%)}100%{transform:translateY(110%)}}
@keyframes rise{0%{transform:translateY(8%);opacity:0}20%{opacity:1}100%{transform:translateY(-30%);opacity:0}}
@keyframes sway{from{transform:translateX(-16px) rotate(-30deg)}to{transform:translateX(16px) rotate(30deg)}}
@keyframes swing{from{transform:translateX(-22px) rotate(-8deg)}to{transform:translateX(22px) rotate(8deg)}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes flutter{from{transform:rotate(-3deg)}to{transform:rotate(3deg)}}
@keyframes flick{0%,100%{transform:scale(1,1) skewX(0)}20%{transform:scale(.92,1.08) skewX(3deg)}45%{transform:scale(1.04,.94) skewX(-2deg)}70%{transform:scale(.96,1.05) skewX(1.5deg)}}
@keyframes glow{0%,100%{opacity:.55}22%{opacity:.9}38%{opacity:.62}61%{opacity:1}80%{opacity:.7}}
@keyframes steam{0%{transform:translateY(0) scaleX(1);opacity:0}18%{opacity:.85}100%{transform:translateY(-80px) scaleX(1.5);opacity:0}}
@keyframes eq{0%,100%{transform:scaleY(.22)}50%{transform:scaleY(1)}}
@keyframes sweep{from{transform:rotate(-16deg)}to{transform:rotate(16deg)}}
@keyframes bob{from{transform:translateY(-10px)}to{transform:translateY(10px)}}
.deco .tw{animation:tw 3.2s ease-in-out infinite}
.deco .fall{animation:fall 14s linear infinite}
.deco .drift{animation:drift 24s linear infinite}
.deco .rise{animation:rise 9s ease-in-out infinite}
.deco .sway{animation:sway 4.5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center}
.deco .swing{animation:swing 5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:center}
.deco .spin{animation:spin 80s linear infinite}
.deco .spinc{animation:spin 20s linear infinite;transform-box:fill-box;transform-origin:center}
.deco .flutter{animation:flutter 3.4s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 0}
.deco .flick{animation:flick 1.3s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.deco .glow{animation:glow 2.6s ease-in-out infinite}
.deco .steam{animation:steam 5s ease-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.deco .eq{animation:eq 1.1s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 100%}
.deco .sweep{animation:sweep 9s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 0}
.deco .bob{animation:bob 6s ease-in-out infinite alternate}
@media (prefers-reduced-motion:reduce){.deco *{animation:none!important}}
